            margin-left: 5px; }
.me-hero { position: relative; padding: 14px 15px 12px; text-align: left; }
.me-htop { display: flex; align-items: flex-start; gap: 13px; }
.me-bulle { position: relative; flex: 0 0 auto; width: 74px; height: 74px;
            z-index: 1; }
